// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListChannels The four channels in display order
	// (GET /channels)
	ListChannels(ctx context.Context, request ListChannelsRequestObject) (ListChannelsResponseObject, error)
	// DeleteComment Delete your comment; a placeholder stays if it has replies
	// (DELETE /comments/{comment_id})
	DeleteComment(ctx context.Context, request DeleteCommentRequestObject) (DeleteCommentResponseObject, error)
	// UpdateComment Edit your comment; it is screened again
	// (PATCH /comments/{comment_id})
	UpdateComment(ctx context.Context, request UpdateCommentRequestObject) (UpdateCommentResponseObject, error)
	// ListMyPending Your posts and comments waiting for review
	// (GET /me/pending)
	ListMyPending(ctx context.Context, request ListMyPendingRequestObject) (ListMyPendingResponseObject, error)
	// ListPosts A channel's published posts, or every channel when channel is empty. Pinned posts come on the first page only.
	// (GET /posts)
	ListPosts(ctx context.Context, request ListPostsRequestObject) (ListPostsResponseObject, error)
	// CreatePost Write a post. It is screened first and may be held for review.
	// (POST /posts)
	CreatePost(ctx context.Context, request CreatePostRequestObject) (CreatePostResponseObject, error)
	// DeletePost Delete your post (kept 90 days for appeals, then purged)
	// (DELETE /posts/{post_id})
	DeletePost(ctx context.Context, request DeletePostRequestObject) (DeletePostResponseObject, error)
	// GetThread A post with its comments (two levels). Unpublished posts are visible to their author only.
	// (GET /posts/{post_id})
	GetThread(ctx context.Context, request GetThreadRequestObject) (GetThreadResponseObject, error)
	// UpdatePost Edit your post; it is screened again
	// (PATCH /posts/{post_id})
	UpdatePost(ctx context.Context, request UpdatePostRequestObject) (UpdatePostResponseObject, error)
	// CreateComment Comment on a post, or reply to a comment. Replies to replies attach to the top-level comment.
	// (POST /posts/{post_id}/comments)
	CreateComment(ctx context.Context, request CreateCommentRequestObject) (CreateCommentResponseObject, error)
	// SetPostPinned Pin or unpin a published post (managers)
	// (PUT /posts/{post_id}/pin)
	SetPostPinned(ctx context.Context, request SetPostPinnedRequestObject) (SetPostPinnedResponseObject, error)
	// SearchPosts Search published posts by title and body; works without diacritics
	// (GET /search)
	SearchPosts(ctx context.Context, request SearchPostsRequestObject) (SearchPostsResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

